def L_pq_macro():
    S, M = 'e15.pq.gdp', 'e15.pq.money'
    return dict(
        id=f'{CID}-pq-macro', title=T('GDP, inflation and money (predicted 8)', 'GDP、通胀和货币（预测题 8）'),
        description=T('What GDP counts and what it leaves out, nominal against real GDP, the GDP deflator and inflation, and the quantity theory of money and the nominal interest rate.', 'GDP 计算什么、不计算什么，名义 GDP 和实际 GDP，GDP 平减指数和通胀，以及货币数量论和名义利率。'),
        minutes=35,
        skills=[{'id': S, 'name': T('Measuring GDP', '衡量 GDP')}, {'id': M, 'name': T('Money, inflation and interest', '货币、通胀与利率')}],
        misconceptions=[{'id': 'nominal-growth', 'description': T('Reading the growth of nominal GDP as growth in what is produced', '把名义 GDP 的增长当成产量的增长')}],
        steps=[
            read('question', T('Predicted question 8, as it could be printed', '预测题 8：可能的原题'),
                 paper(PQ(8, 14),
                       T(r"An economy produces only pizzas and haircuts. In 2024 it produced 100 pizzas at \$10 and 50 haircuts at \$20; in 2025, 120 pizzas at \$11 and 60 haircuts at \$24.", r"某经济体只生产比萨和理发。2024 年生产了 100 个比萨，每个 10，和 50 次理发，每次 20；2025 年生产了 120 个比萨，每个 11，和 60 次理发，每次 24。"),
                       T(r"**a.** Calculate nominal GDP in both years, real GDP in 2025 at 2024 prices, and the growth rate of real GDP. (4 marks)", r"**a.** 计算两年的名义 GDP、以 2024 年价格计算的 2025 年实际 GDP，以及实际 GDP 增长率。（4 分）"),
                       T(r"**b.** Calculate the GDP deflator for 2025 (2024 = 100) and the inflation rate it shows. (2 marks)", r"**b.** 计算 2025 年的 GDP 平减指数（2024 = 100），以及它反映的通胀率。（2 分）"),
                       T(r"**c.** For each, say whether it counts in this economy's 2025 GDP, and why: (i) a used car sold in 2025; (ii) flour bought by a pizza shop; (iii) a pension paid by the government; (iv) a new house built in 2025. (4 marks)", r"**c.** 下面各项是否计入该经济体 2025 年的 GDP，为什么：(i) 2025 年卖出的一辆二手车；(ii) 比萨店买的面粉；(iii) 政府发的养老金；(iv) 2025 年新建的一栋房子。（4 分）"),
                       T(r"**d.** The money supply grows 8% a year, real GDP 3% a year, and the velocity of money is constant. Use the quantity theory of money to find the inflation rate. If lenders want a real interest rate of 2%, what nominal interest rate will they charge? (4 marks)", r"**d.** 货币供应量每年增长 8%，实际 GDP 每年增长 3%，货币流通速度不变。用货币数量论求通胀率。如果贷款人要求 2% 的实际利率，他们会收多少名义利率？（4 分）")),
                 callout('note', T('Why this is a likely question', '为什么这道题很可能考'),
                         T(r"Measuring GDP opens the course, and money, inflation, interest rates and policy are part of its macroeconomics; the mock had none of them. Treat this one as the least certain of the eight: the lectures may weight it differently.", r"衡量 GDP 是这门课的第一讲，货币、通胀、利率和政策也属于它的宏观部分；模考一样都没考。把这道题看作八道里最不确定的一道：课上的侧重可能不同。")),
                 h(T('Reading it slowly', '慢慢读一遍')),
                 ul(T(r"**Nominal GDP**: everything produced, valued at that year's prices. **Real GDP**: the same quantities valued at the prices of a base year (here 2024), so that only quantities can change it.", r"**名义 GDP**：所有产出按当年价格计价。**实际 GDP**：同样的数量按基年（这里是 2024 年）价格计价，这样只有数量能让它变化。"),
                    T(r"**GDP deflator**: a price index made from the two: nominal GDP divided by real GDP, times 100.", r"**GDP 平减指数**：由两者算出的价格指数：名义 GDP 除以实际 GDP，再乘 100。"),
                    T(r"**Velocity of money**: how many times a dollar is spent on output in a year. The **quantity theory** links money to prices through it.", r"**货币流通速度**：一块钱一年里被用来买产出的次数。**货币数量论**通过它把货币和价格联系起来。")),
                 chapter=Q_CH()),
            read('real', T('Nominal and real: separating prices from quantities', '名义与实际：把价格和数量分开'),
                 paper(PART_M('a', 4), T(r"Calculate nominal GDP in both years, real GDP in 2025 at 2024 prices, and the growth rate of real GDP.", r"计算两年的名义 GDP、以 2024 年价格计算的 2025 年实际 GDP，以及实际 GDP 增长率。")),
                 p(T(r"**GDP** is the market value of all *final* goods and services produced in a country in a period. To add pizzas and haircuts, value each at its price. That gives nominal GDP, which rose from 2000 to 2760, by 38%. But part of that rise is only prices going up: the economy did not produce 38% more.",
                     r"**GDP** 是一个国家在一段时间内生产的全部*最终*商品和服务的市场价值。要把比萨和理发加在一起，就按各自的价格计价。这就是名义 GDP，从 2000 增到 2760，涨了 38%。但其中一部分只是价格在涨：经济并没有多生产 38%。")),
                 p(T(r"To see the quantities alone, value 2025's output at 2024's prices: real GDP. If every quantity rose 20% (as here: 100 → 120 pizzas, 50 → 60 haircuts), real GDP rises exactly 20%. That is the growth an economist means by *economic growth*.",
                     r"要只看数量，就把 2025 年的产出按 2024 年的价格计价：这就是实际 GDP。如果每样东西的数量都涨了 20%（这里正是这样：比萨 100 → 120，理发 50 → 60），实际 GDP 就正好涨 20%。经济学家说的*经济增长*指的就是它。")),
                 table([T('Item', '项目'), T('2024 at 2024 prices', '2024 年·2024 年价格'), T('2025 at 2025 prices', '2025 年·2025 年价格'), T('2025 at 2024 prices', '2025 年·2024 年价格')],
                       [T('Pizzas', '比萨'), '100 × 10 = 1000', '120 × 11 = 1320', '120 × 10 = 1200'],
                       [T('Haircuts', '理发'), '50 × 20 = 1000', '60 × 24 = 1440', '60 × 20 = 1200'],
                       [T('Total', '合计'), T('2000 (nominal = real)', '2000（名义 = 实际）'), T('2760 (nominal)', '2760（名义）'), T('2400 (real)', '2400（实际）')]),
                 quiz(T(r"Nominal GDP rose 38% while real GDP rose 20%. What does the gap mean?", r"名义 GDP 涨了 38%，实际 GDP 涨了 20%。差距说明什么？"),
                      [(T('Prices rose: the rest of the nominal increase is inflation', '价格上涨了：名义增长中多出来的部分是通胀'), True),
                       (T('The economy produced 38% more', '经济多生产了 38%'), T(r"Only 20% more; the rest is higher prices.", r"只多生产了 20%；其余是价格上涨。"), 'nominal-growth'),
                       (T('Real GDP was measured wrongly', '实际 GDP 算错了'), T(r"Real GDP is meant to leave out price changes.", r"实际 GDP 本来就是要剔除价格变化。"))],
                      T(r"Nominal growth ≈ real growth + inflation: $1.38 = 1.20 \times 1.15$.", r"名义增长 ≈ 实际增长 + 通胀：$1.38 = 1.20 \times 1.15$。")),
                 chapter=PART('a')),
            derive('q8ab', T('Parts (a) and (b), worked', '(a)(b) 小问：完整解法'),
                   [('Y_{2024} = 100 \\times 10 + 50 \\times 20 = 2000', T(r"Nominal GDP 2024: quantities at that year's prices.", r"2024 年名义 GDP：数量乘当年价格。")),
                    ('Y_{2025} = 120 \\times 11 + 60 \\times 24 = 2760', T(r"Nominal GDP 2025.", r"2025 年名义 GDP。")),
                    ('Y^{r}_{2025} = 120 \\times 10 + 60 \\times 20 = 2400', T(r"Real GDP 2025: 2025's quantities at 2024's prices.", r"2025 年实际 GDP：2025 年的数量乘 2024 年的价格。")),
                    ('g = \\frac{2400 - 2000}{2000} = 20\\%', T(r"Real growth (2024's real GDP equals its nominal, as the base year).", r"实际增长率（基年 2024 年的实际 GDP 等于名义 GDP）。")),
                    ('D_{2025} = \\frac{2760}{2400} \\times 100 = 115', T(r"(b) The deflator: nominal over real, times 100.", r"(b) 平减指数：名义除以实际，乘 100。")),
                    ('\\pi = \\frac{115 - 100}{100} = 15\\%', T(r"Inflation: the rise in the deflator from the base year's 100.", r"通胀率：平减指数从基年的 100 上升了多少。"))],
                   outro=T(r"**Answer:** nominal GDP 2000 (2024) and 2760 (2025); real GDP 2025 = 2400; real growth 20%; deflator 115, inflation 15%.", r"**答案：** 名义 GDP 2000（2024）和 2760（2025）；2025 年实际 GDP = 2400；实际增长 20%；平减指数 115，通胀 15%。"),
                   blank=(2, '2400', T(r"2025's quantities at 2024's prices.", r"2025 年的数量乘 2024 年的价格。")), skill=S),
            read('counts', T('What counts in GDP', 'GDP 算什么'),
                 paper(PART_M('c', 4), T(r"Say whether each counts in this economy's 2025 GDP, and why: (i) a used car sold in 2025; (ii) flour bought by a pizza shop; (iii) a pension paid by the government; (iv) a new house built in 2025.", r"下面各项是否计入 2025 年 GDP，为什么：(i) 2025 年卖出的一辆二手车；(ii) 比萨店买的面粉；(iii) 政府发的养老金；(iv) 2025 年新建的一栋房子。")),
                 p(T(r"Every item is a test of one word in the definition: *market value* of *final* goods and services *produced* in the country *in the period*.", r"每一项都是在考定义里的一个词：本国*在这段时间内生产*的*最终*商品和服务的*市场价值*。")),
                 ul(T(r"**(i) The used car: no.** It was produced, and counted, in the year it was made; selling it again produces nothing new. (A dealer's margin on it does count: that is a service produced now.)", r"**(i) 二手车：不算。** 它在生产的那一年已经算过了；再卖一次没有生产出新东西。（经销商从中赚的差价算：那是现在提供的服务。）"),
                    T(r"**(ii) The flour: no.** It is an *intermediate* good, used up in making pizzas. Its value is already inside the price of the pizza; counting it again would count it twice.", r"**(ii) 面粉：不算。** 它是*中间*品，在做比萨时用掉了。它的价值已经包含在比萨的价格里；再算一次就重复计算了。"),
                    T(r"**(iii) The pension: no.** It is a *transfer*: money moves from taxpayers to retirees, but nothing is produced in exchange. (When the retiree spends it, that spending counts, as consumption.)", r"**(iii) 养老金：不算。** 它是*转移支付*：钱从纳税人转到退休者手里，但没有生产任何东西作为交换。（退休者把钱花掉时，那笔支出算作消费。）"),
                    T(r"**(iv) The new house: yes.** It is a final good produced in 2025. In the expenditure approach, $Y = C + I + G + NX$, it counts as **investment** $I$, not consumption.", r"**(iv) 新房：算。** 它是 2025 年生产的最终品。在支出法 $Y = C + I + G + NX$ 里，它算作**投资** $I$，不算消费。")),
                 chapter=PART('c')),
            read('money', T('Money, prices and the interest rate', '货币、价格和利率'),
                 paper(PART_M('d', 4), T(r"The money supply grows 8% a year, real GDP 3% a year, and the velocity of money is constant. Use the quantity theory of money to find the inflation rate. If lenders want a real interest rate of 2%, what nominal interest rate will they charge?", r"货币供应量每年增长 8%，实际 GDP 每年增长 3%，货币流通速度不变。用货币数量论求通胀率。如果贷款人要求 2% 的实际利率，他们会收多少名义利率？")),
                 p(T(r"Total spending on output can be counted two ways. As money times how often it is spent: $M \times V$. Or as the price level times real output: $P \times Y$, which is nominal GDP. They are the same spending, so:", r"花在产出上的总支出可以用两种方法数。一种是货币量乘它被花的次数：$M \times V$。另一种是价格水平乘实际产出：$P \times Y$，也就是名义 GDP。两者是同一笔支出，所以：")),
                 math_(r"M V = P Y \quad\Rightarrow\quad \%\Delta M + \%\Delta V \approx \%\Delta P + \%\Delta Y"),
                 p(T(r"(For growth rates, a product becomes a sum.) If velocity is constant, money growing faster than real output must show up as rising prices: inflation is money growth minus real growth. That is the quantity theory's long-run message: inflation is, at bottom, too much money chasing too few goods.",
                     r"（对增长率来说，乘积变成和。）如果流通速度不变，货币增长快于实际产出增长的部分，必然表现为价格上涨：通胀率 = 货币增长率 − 实际增长率。这就是货币数量论的长期结论：通胀说到底是太多的钱追逐太少的商品。")),
                 p(T(r"A lender who wants 2% more *goods* back next year must also be paid for the 5% by which each dollar will have lost value. So the **nominal** interest rate is roughly the real rate plus expected inflation: the **Fisher equation**, $i \approx r + \pi$. Central banks work through it: by setting the nominal rate (in Australia, the RBA's cash rate) above or below inflation, they make borrowing dearer or cheaper in real terms.",
                     r"贷款人如果想明年多收回 2% 的*商品*，还得补偿每块钱贬值的 5%。所以**名义**利率约等于实际利率加预期通胀：这就是**费雪方程**，$i \approx r + \pi$。中央银行就是通过它起作用的：把名义利率（在澳大利亚是 RBA 的现金利率）定得高于或低于通胀，让借钱在实际上变贵或变便宜。")),
                 quiz(T(r"Money grows 8%, velocity is constant, and real output grows 8% too. What does the quantity theory predict for inflation?", r"货币增长 8%，流通速度不变，实际产出也增长 8%。货币数量论预测通胀是多少？"),
                      [(T('About zero: the extra money buys the extra output', '大约为零：多出来的钱买的是多出来的产出'), True),
                       (T('8%, the money growth', '8%，也就是货币增长率'), T(r"Only if real output does not grow.", r"只有实际产出不增长时才是。")),
                       (T('16%', '16%'), T(r"Real growth is subtracted, not added.", r"实际增长率要减去，不是加上。"))],
                      T(r"$\%\Delta P \approx 8 + 0 - 8 = 0$.", r"$\%\Delta P \approx 8 + 0 - 8 = 0$。")),
                 chapter=PART('d')),
            derive('q8d', T('Part (d), worked', '(d) 小问：完整解法'),
                   [('\\%\\Delta M + \\%\\Delta V = \\%\\Delta P + \\%\\Delta Y', T(r"The quantity theory in growth rates.", r"增长率形式的货币数量论。")),
                    ('8 + 0 = \\pi + 3', T(r"Money grows 8%, velocity is constant, real output grows 3%:", r"货币增长 8%，流通速度不变，实际产出增长 3%：")),
                    ('\\pi = 5\\%', T(r"Inflation: money growth beyond real growth.", r"通胀率：货币增长中超出实际增长的部分。")),
                    ('i \\approx r + \\pi = 2 + 5 = 7\\%', T(r"The Fisher equation: the real rate plus inflation.", r"费雪方程：实际利率加通胀率。"))],
                   outro=T(r"**Answer:** inflation is about 5%; lenders charge a nominal rate of about 7%.", r"**答案：** 通胀约 5%；贷款人收取约 7% 的名义利率。"),
                   blank=(2, '5', T(r"From $8 + 0 = \pi + 3$.", r"由 $8 + 0 = \pi + 3$。")), skill=M),
            read('paper-answer', T('A full-mark answer', '一份满分答案'),
                 paper(PQA(8),
                       T(r"**a.** Nominal GDP 2024 $= 1000 + 1000 = 2000$; 2025 $= 1320 + 1440 = 2760$. Real GDP 2025 (2024 prices) $= 1200 + 1200 = 2400$. Real growth $= (2400 - 2000)/2000 = 20\%$.", r"**a.** 2024 年名义 GDP $= 1000 + 1000 = 2000$；2025 年 $= 1320 + 1440 = 2760$。2025 年实际 GDP（2024 年价格）$= 1200 + 1200 = 2400$。实际增长 $= (2400 - 2000)/2000 = 20\%$。"),
                       T(r"**b.** Deflator 2025 $= 2760/2400 \times 100 = 115$; inflation $= 15\%$.", r"**b.** 2025 年平减指数 $= 2760/2400 \times 100 = 115$；通胀 $= 15\%$。"),
                       T(r"**c.** (i) No: produced and counted in an earlier year (only a dealer's margin counts). (ii) No: an intermediate good, already included in the pizza's value. (iii) No: a transfer payment, not payment for production. (iv) Yes: a final good produced in 2025, counted as investment.", r"**c.** (i) 不算：在以前的年份生产并计算过（只有经销商的差价算）。(ii) 不算：中间品，已包含在比萨的价值里。(iii) 不算：转移支付，不是对生产的报酬。(iv) 算：2025 年生产的最终品，计入投资。"),
                       T(r"**d.** $MV = PY \Rightarrow \%\Delta M + \%\Delta V = \%\Delta P + \%\Delta Y$: $8 + 0 = \pi + 3$, so $\pi = 5\%$. Fisher: $i \approx r + \pi = 2 + 5 = 7\%$.", r"**d.** $MV = PY \Rightarrow \%\Delta M + \%\Delta V = \%\Delta P + \%\Delta Y$：$8 + 0 = \pi + 3$，所以 $\pi = 5\%$。费雪方程：$i \approx r + \pi = 2 + 5 = 7\%$。"),
                       answer=True),
                 p(T(r"Where the marks are: in (c) a reason for each item, taken from the definition of GDP; in (d) the quantity equation written in growth rates before you use it.", r"得分点：(c) 每一项都要从 GDP 的定义给出理由；(d) 先写出增长率形式的数量方程，再代数。")),
                 chapter=PAPER_CH()),
            read('wider', T('Policy, and the other ways to measure GDP', '政策，以及衡量 GDP 的其他方法'),
                 ul(T(r"**Three ways to measure GDP**, which must agree: total spending on final goods ($C + I + G + X - M$); total value added (each firm's sales minus its purchases from other firms, which is how intermediate goods are kept out); total income (wages, profits, rent, interest).", r"**衡量 GDP 的三种方法**，结果必须一致：最终品的总支出（$C + I + G + X - M$）；总增加值（每家企业的销售额减去从其他企业买的投入，中间品就是这样被排除的）；总收入（工资、利润、租金、利息）。"),
                    T(r"**What GDP misses**: home production, leisure, the environment, how income is shared. It measures production, not well-being.", r"**GDP 漏掉的东西**：家庭劳动、闲暇、环境、收入怎么分配。它衡量的是生产，不是福祉。"),
                    T(r"**Monetary policy**: the central bank raises its cash rate to cool spending and inflation (borrowing dearer, saving more attractive, a stronger dollar), and lowers it to support spending.", r"**货币政策**：央行提高现金利率来给支出和通胀降温（借钱更贵、储蓄更有吸引力、本币走强），降低利率来支持支出。"),
                    T(r"**Fiscal policy**: government spending and taxes. More spending or lower taxes raise total demand in the short run; financed by borrowing, they can push interest rates up.", r"**财政政策**：政府支出和税收。增加支出或减税在短期内提高总需求；如果靠借债融资，可能推高利率。"),
                    T(r"**A business reads all of this** as its environment: real growth for demand, inflation for costs and prices, interest rates for the cost of investment.", r"**企业把这些都看作自己的经营环境**：实际增长关系到需求，通胀关系到成本和定价，利率关系到投资的成本。")),
                 h(T('Traps', '易错点')),
                 ul(T(r"Valuing real GDP at the current year's prices instead of the base year's.", r"用当年价格而不是基年价格算实际 GDP。"),
                    T(r"Counting intermediate goods or transfers.", r"把中间品或转移支付算进 GDP。"),
                    T(r"Adding real growth to money growth in the quantity theory instead of subtracting it.", r"在货币数量论里把实际增长率加上，而不是减去。")),
                 chapter=WIDER_CH()),
            number('try-deflator', T('Your turn: a deflator', '你来：平减指数'), S,
                   T(r"Nominal GDP is 5500 and real GDP (at base-year prices) is 5000. What is the GDP deflator?", r"名义 GDP 是 5500，实际 GDP（按基年价格）是 5000。GDP 平减指数是多少？"),
                   110, T(r"$5500/5000 \times 100 = 110$: prices are 10% above the base year.", r"$5500/5000 \times 100 = 110$：价格比基年高 10%。"),
                   tolerance=0.01, chapter=TRY_CH()),
            number('try-qtm', T('Your turn: the quantity theory', '你来：货币数量论'), M,
                   T(r"Money grows 6% a year, real output 2%, velocity is constant. What is inflation, in percent?", r"货币每年增长 6%，实际产出增长 2%，流通速度不变。通胀率是百分之几？"),
                   4, T(r"$6 + 0 - 2 = 4\%$.", r"$6 + 0 - 2 = 4\%$。"), tolerance=0.01),
            choice('try-count', T('Your turn: does it count?', '你来：算不算？'), S,
                   T(r"Which of these counts in this year's GDP?", r"下面哪项计入今年的 GDP？"),
                   [(T('A new machine bought by a bakery this year', '面包店今年买的一台新机器'), True),
                    (T('Shares bought on the stock market', '在股市上买的股票'), T(r"A financial transaction: ownership changes hands, nothing is produced.", r"金融交易：所有权换手，没有生产任何东西。")),
                    (T('Unemployment benefits', '失业救济金'), T(r"A transfer payment.", r"转移支付。"))],
                   T(r"The machine is a final good produced this year, counted as investment.", r"机器是今年生产的最终品，计入投资。")),
        ],
    )
